#include "PluginEditor.h"
using namespace wavemover;
namespace {const juce::Colour orange{0xffff8a36},background{0xff17191c},panel{0xff23262b},text{0xfff1ede5};
void row(juce::Rectangle<int>r,std::initializer_list<juce::Component*>items){const int width=r.getWidth()/static_cast<int>(items.size());for(auto*c:items)c->setBounds(r.removeFromLeft(width).reduced(3,2));}
}
void WaveView::refresh(){auto s=processor.snapshot();if(s.audio!=cachedAudio){cachedAudio=s.audio;peaks.clear();if(cachedAudio&&cachedAudio->frames()){const auto count=std::min<std::size_t>(8192,cachedAudio->frames());peaks.resize(static_cast<std::size_t>(cachedAudio->channels()),std::vector<Peak>(count));for(int c=0;c<cachedAudio->channels();++c)for(std::size_t i=0;i<count;++i){Peak p{1,-1};const auto start=i*cachedAudio->frames()/count,end=(i+1)*cachedAudio->frames()/count;for(auto j=start;j<end;++j){p.low=std::min(p.low,cachedAudio->data[c][j]);p.high=std::max(p.high,cachedAudio->data[c][j]);}peaks[c][i]=p;}}}repaint();}
std::size_t WaveView::at(float x)const{auto s=processor.snapshot();if(!s.audio)return 0;return std::min(s.audio->frames(),static_cast<std::size_t>(std::max(0.,viewStart+viewSize*std::clamp(static_cast<double>(x)/std::max(1,getWidth()),0.,1.))*static_cast<double>(s.audio->frames())));}
void WaveView::paint(juce::Graphics&g){g.fillAll(panel);auto s=processor.snapshot();if(!s.audio||!s.audio->frames()){g.setColour(text.withAlpha(.8f));g.setFont(20.f);g.drawFittedText("Solte um arquivo de audio aqui\nou use Abrir audio / Capturar pista",getLocalBounds().reduced(30),juce::Justification::centred,3);return;}
    const auto n=s.audio->frames();const auto x=[&](double p){return static_cast<float>((p/static_cast<double>(n)-viewStart)/viewSize*getWidth());};const auto sel=bounded(s.selection,n);
    const float left=x(static_cast<double>(sel.begin)),right=x(static_cast<double>(sel.end));g.setColour(orange.withAlpha(.13f));g.fillRect(left,24.f,right-left,static_cast<float>(getHeight()-24));
    g.setFont(12.f);for(int i=0;i<=8;++i){const float px=getWidth()*i/8.f;const double sec=(viewStart+viewSize*i/8.)*static_cast<double>(n)/s.audio->rate;g.setColour(text.withAlpha(.5f));g.drawText(juce::String(sec,2)+"s",static_cast<int>(px)+4,2,80,18,juce::Justification::left);g.setColour(text.withAlpha(.06f));g.drawVerticalLine(static_cast<int>(px),24.f,static_cast<float>(getHeight()));}
    const int laneHeight=(getHeight()-32)/s.audio->channels();for(int c=0;c<s.audio->channels();++c){const float cy=32.f+laneHeight*(c+.5f);g.setColour(text.withAlpha(.12f));g.drawHorizontalLine(static_cast<int>(cy),0,static_cast<float>(getWidth()));g.setColour(orange);
        for(int px=0;px<getWidth();++px){const auto begin=at(static_cast<float>(px)),end=std::max(begin+1,at(static_cast<float>(px+1)));float lo=0,hi=0;
            if(!peaks.empty()&&peaks[c].size()&&end-begin>=n/peaks[c].size()){const auto p0=std::min(peaks[c].size()-1,begin*peaks[c].size()/n),p1=std::min(peaks[c].size(),end*peaks[c].size()/n+1);for(auto j=p0;j<p1;++j){lo=std::min(lo,peaks[c][j].low);hi=std::max(hi,peaks[c][j].high);}}
            else for(auto j=begin;j<std::min(end,n);++j){lo=std::min(lo,s.audio->data[c][j]);hi=std::max(hi,s.audio->data[c][j]);}
            g.drawVerticalLine(px,cy-std::min(1.f,hi)*laneHeight*.43f,cy-std::max(-1.f,lo)*laneHeight*.43f+1);}}
    for(auto mark:s.markers){g.setColour(text.withAlpha(.45f));g.drawVerticalLine(static_cast<int>(x(static_cast<double>(mark))),24.f,static_cast<float>(getHeight()));}
    g.setColour(orange);g.drawVerticalLine(static_cast<int>(left),24.f,static_cast<float>(getHeight()));g.drawVerticalLine(static_cast<int>(right),24.f,static_cast<float>(getHeight()));
    if(sel.end>sel.begin){g.fillEllipse(left+2,27,10,10);g.fillEllipse(right-12,27,10,10);}
    if(fadeMode){const auto frames=fadeMs*s.audio->rate*.001;juce::Path shape;if(fadeMode==1){shape.startNewSubPath(left,static_cast<float>(getHeight()));shape.lineTo(left,44);shape.lineTo(x(static_cast<double>(sel.begin)+frames),static_cast<float>(getHeight()));}else{shape.startNewSubPath(right,static_cast<float>(getHeight()));shape.lineTo(right,44);shape.lineTo(x(static_cast<double>(sel.end)-frames),static_cast<float>(getHeight()));}shape.closeSubPath();g.setColour(orange.withAlpha(.25f));g.fillPath(shape);}
    g.setColour(text.withAlpha(.75f));g.drawVerticalLine(static_cast<int>(x(static_cast<double>(cursor))),24.f,static_cast<float>(getHeight()));if(processor.playing()){g.setColour(juce::Colours::white);g.drawVerticalLine(static_cast<int>(x(processor.playbackFraction()*static_cast<double>(n))),24.f,static_cast<float>(getHeight()));}}
void WaveView::mouseDown(const juce::MouseEvent&e){if(!editable)return;auto s=processor.snapshot();if(!s.audio)return;grabKeyboardFocus();cursor=at(e.position.x);anchor=cursor;dragged=false;fadeMode=0;
    if(e.mods.isPopupMenu()){if(onContext)onContext();return;}
    const auto pixel=[&](std::size_t p){return (static_cast<double>(p)/static_cast<double>(s.audio->frames())-viewStart)/viewSize*getWidth();};
    if(e.y>=24&&e.y<43&&s.selection.end>s.selection.begin){if(std::abs(e.position.x-pixel(s.selection.begin)-7)<8)fadeMode=1;else if(std::abs(e.position.x-pixel(s.selection.end)+7)<8)fadeMode=2;}
    if(!fadeMode){if(e.mods.isShiftDown()){anchor=s.selection.begin;processor.setSelection({std::min(anchor,cursor),std::max(s.selection.end,cursor)});}else processor.setSelection({cursor,cursor});}if(onSelection)onSelection();repaint();}
void WaveView::mouseDrag(const juce::MouseEvent&e){if(!editable||e.mods.isPopupMenu())return;dragged=e.getDistanceFromDragStart()>3;const auto p=at(e.position.x);auto s=processor.snapshot();if(!s.audio)return;
    if(fadeMode){const auto frames=fadeMode==1?(p>s.selection.begin?p-s.selection.begin:0):(s.selection.end>p?s.selection.end-p:0);fadeMs=std::min(static_cast<double>(s.selection.end-s.selection.begin),static_cast<double>(frames))*1000/s.audio->rate;}
    else if(dragged){cursor=p;processor.setSelection({std::min(anchor,p),std::max(anchor,p)});}if(onSelection)onSelection();repaint();}
void WaveView::mouseUp(const juce::MouseEvent&e){if(!editable||e.mods.isPopupMenu())return;auto s=processor.snapshot();if(!s.audio)return;
    if(fadeMode){if(dragged&&onFade)onFade(fadeMode==1,fadeMs);fadeMode=0;}
    else if(!dragged&&!e.mods.isShiftDown()&&!e.mods.isAltDown()){auto upper=std::upper_bound(s.markers.begin(),s.markers.end(),cursor);const auto end=upper==s.markers.end()?s.audio->frames():*upper;const auto begin=upper==s.markers.begin()?0:*(upper-1);processor.setSelection({begin,end});}
    if(onSelection)onSelection();repaint();}
void WaveView::mouseDoubleClick(const juce::MouseEvent&){if(!editable)return;auto s=processor.snapshot();if(s.audio)processor.setSelection({0,s.audio->frames()});if(onSelection)onSelection();repaint();}
void WaveView::mouseWheelMove(const juce::MouseEvent&e,const juce::MouseWheelDetails&w){if(e.mods.isShiftDown())viewStart=std::clamp(viewStart-w.deltaY*viewSize*.4,0.,1.-viewSize);else{const double anchorPoint=viewStart+viewSize*e.position.x/std::max(1,getWidth());viewSize=std::clamp(viewSize*std::exp(-w.deltaY*2),.0001,1.);viewStart=std::clamp(anchorPoint-viewSize*e.position.x/std::max(1,getWidth()),0.,1.-viewSize);}repaint();}

WaveMoverEditor::WaveMoverEditor(WaveMoverProcessor&p):AudioProcessorEditor(p),processor(p),wave(p){
    style.setColour(juce::TextButton::buttonColourId,juce::Colour(0xff34383e));style.setColour(juce::TextButton::textColourOffId,text);style.setColour(juce::Slider::thumbColourId,orange);style.setColour(juce::Slider::trackColourId,orange);style.setColour(juce::ComboBox::backgroundColourId,panel);style.setColour(juce::Label::textColourId,text);setLookAndFeel(&style);setWantsKeyboardFocus(true);wave.setWantsKeyboardFocus(true);
    for(auto*c:std::vector<juce::Component*>{&wave,&open,&capture,&play,&stop,&original,&loop,&all,&split,&grid,&attacks,&clear,&undo,&redo,&cut,&copy,&paste,&duplicate,&trim,&crossfade,&restore,&effects,&gridDivision,&a,&b,&bpm,&labelA,&labelB,&labelBpm,&information,&status,&details,&seed,&apply,&save,&fit,&drag,&exportSelection})addAndMakeVisible(c);
    for(auto*s:{&a,&b,&bpm}){s->setSliderStyle(juce::Slider::LinearHorizontal);s->setTextBoxStyle(juce::Slider::TextBoxRight,false,95,26);}
    bpm.setRange(20,400,.01);bpm.setValue(120);labelBpm.setText("BPM da grade",juce::dontSendNotification);gridDivision.addItem("1 tempo",1);gridDivision.addItem("1/2 tempo",2);gridDivision.addItem("1/4 tempo",4);gridDivision.addItem("1/8 tempo",8);gridDivision.addItem("Tercina",3);gridDivision.setSelectedId(4);
    const std::vector<std::pair<Op,juce::String>>list{{Op::Reverse,"Reverse"},{Op::FadeIn,"Fade in"},{Op::FadeOut,"Fade out"},{Op::FadeBoth,"Fade nas duas pontas"},{Op::Stretch,"Esticar / encurtar (mantem afinacao)"},{Op::Pitch,"Afinacao (mantem duracao)"},{Op::Tempo,"BPM de origem para BPM de destino"},{Op::TempoRamp,"Rampa de tempo (mantem afinacao)"},{Op::Speed,"Velocidade de fita"},{Op::TapeStop,"Tape stop"},{Op::TapeStart,"Tape start"},{Op::Reverb,"Reverb + cauda"},{Op::Tail,"Somente reverberacao"},{Op::ReverseTail,"Reverberacao invertida"},{Op::Delay,"Delay"},{Op::Lowpass,"Filtro passa-baixas"},{Op::Highpass,"Filtro passa-altas"},{Op::Saturate,"Saturacao"},{Op::Gain,"Ganho"},{Op::Normalize,"Normalizar pico a -1 dBFS"},{Op::Repeat,"Repetir selecao (aumenta duracao)"},{Op::Ratchet,"Ratchet (mantem duracao)"},{Op::PingPong,"Repetir frente / tras"},{Op::Freeze,"Freeze granular"},{Op::Shuffle,"Embaralhar fatias"},{Op::Silence,"Silenciar selecao"}};
    for(const auto&e:list){operations.push_back(e.first);effects.addItem(e.second,static_cast<int>(operations.size()));}effects.onChange=[this]{configureEffect();};effects.setSelectedId(1);
    seed.setText("1984");seed.setInputRestrictions(10,"0123456789");seed.setTooltip("Semente: repetir o numero reproduz a mesma variacao granular ou ordem de fatias.");
    open.onClick=[this]{chooser=std::make_unique<juce::FileChooser>("Abrir audio",juce::File{},"*.wav;*.aif;*.aiff;*.flac;*.mp3;*.ogg");chooser->launchAsync(juce::FileBrowserComponent::openMode|juce::FileBrowserComponent::canSelectFiles,[safe=juce::Component::SafePointer<WaveMoverEditor>(this)](const juce::FileChooser&f){if(safe&&f.getResult().existsAsFile())safe->openFile(f.getResult());});};
    capture.onClick=[this]{try{if(processor.recording()||processor.captureReady()){const bool loaded=processor.finishCapture();status.setText(loaded?"Captura pronta para editar.":"Captura vazia. Reproduza a pista enquanto captura.",juce::dontSendNotification);}else{processor.startCapture();status.setText("Capturando a entrada. Reproduza a pista na DAW e clique Finalizar captura.",juce::dontSendNotification);}}catch(const std::exception&e){status.setText(e.what(),juce::dontSendNotification);}updateControls();};
    play.onClick=[this]{processor.play(false,loop.getToggleState());status.setText("Previa pela saida do plugin; mantenha o motor de audio da DAW ativo.",juce::dontSendNotification);};stop.onClick=[this]{processor.stop();};original.onClick=[this]{processor.play(true,loop.getToggleState());};
    all.onClick=[this]{auto s=processor.snapshot();if(s.audio)processor.setSelection({0,s.audio->frames()});wave.repaint();};
    split.onClick=[this]{auto s=processor.snapshot();if(!s.audio)return;s.markers.push_back(wave.cursor);processor.setMarkers(std::move(s.markers),"Split manual");};
    grid.onClick=[this]{auto s=processor.snapshot();if(s.audio)processor.setMarkers(wavemover::grid(*s.audio,bpm.getValue(),gridDivision.getSelectedId()),"Split pela grade");};
    attacks.onClick=[this]{auto s=processor.snapshot();if(!s.audio)return;auto*p=&processor;work("Detectando ataques...",[s,p]{auto m=transients(*s.audio,.5);return[p,m=std::move(m)]()mutable{p->setMarkers(std::move(m),"Split por ataques");};});};
    clear.onClick=[this]{processor.setMarkers({},"Splits removidos");};undo.onClick=[this]{processor.undo();};redo.onClick=[this]{processor.redo();};
    cut.onClick=[this]{applyOperation(Op::Delete,{},"Apagar selecao");};copy.onClick=[this]{copyAudio();};paste.onClick=[this]{pasteAudio();};duplicate.onClick=[this]{applyOperation(Op::Duplicate,{},"Duplicar");};trim.onClick=[this]{applyOperation(Op::Trim,{},"Manter selecao");};restore.onClick=[this]{processor.restoreOriginal();};
    crossfade.onClick=[this]{auto s=processor.snapshot();if(!s.audio)return;const auto cursor=wave.cursor;auto*p=&processor;const double ms=a.getValue();work("Crossfade no cursor...",[s,cursor,ms,p]{auto out=std::make_shared<Clip>(crossfadeAt(*s.audio,cursor,std::clamp(ms,1.,1000.)));const auto removed=s.audio->frames()-out->frames();std::vector<std::size_t>marks;for(auto m:s.markers)if(m<cursor-removed)marks.push_back(m);else if(m>cursor+removed)marks.push_back(m-removed);return[p,out,marks=std::move(marks),cursor,removed]()mutable{p->commit(std::move(*out),std::move(marks),{cursor-removed,cursor},"Crossfade (sobreposicao)");};});};
    apply.onClick=[this]{const auto i=effects.getSelectedId()-1;if(i>=0&&i<static_cast<int>(operations.size()))applyOperation(operations[static_cast<std::size_t>(i)],{a.getValue(),b.getValue(),static_cast<std::uint32_t>(seed.getText().getLargeIntValue())},effects.getText());};
    save.onClick=[this]{exportAudio(false);};drag.onClick=[this]{if(!drag.readyFile.existsAsFile())exportAudio(true);};exportSelection.onClick=[this]{drag.readyFile={};drag.setButtonText("Preparar arraste");};fit.onClick=[this]{wave.viewStart=0;wave.viewSize=1;wave.repaint();};
    wave.onContext=[this]{contextMenu();};wave.onSelection=[this]{drag.readyFile={};drag.setButtonText("Preparar arraste");};wave.onFade=[this](bool in,double ms){applyOperation(in?Op::FadeIn:Op::FadeOut,{ms,1,0},in?"Fade in pela alca":"Fade out pela alca");};
    crossfade.setTooltip("Sobrepoe os dois lados do cursor pelo valor A em milissegundos (1 a 1000). Encurta o audio pelo tempo sobreposto.");
    split.setTooltip("Clique para posicionar o cursor; este botao cria a divisao. Clique numa fatia para seleciona-la.");attacks.setTooltip("Sugere cortes por ataques; marcadores podem ser removidos em Limpar splits e recriados manualmente.");
    details.setText("Arraste para selecionar | Clique: fatia | Shift: estender | Alt+clique: cursor | Roda: zoom | Shift+roda: mover | Alcas laranja: fades",juce::dontSendNotification);details.setFont(juce::Font(12.f));
    status.setText("Sem efeitos aplicados. Abra um arquivo ou capture ate 120 segundos da entrada.",juce::dontSendNotification);
    setResizable(true,true);setResizeLimits(1040,700,1800,1200);setSize(1180,780);startTimerHz(12);updateControls();
}
WaveMoverEditor::~WaveMoverEditor(){stopTimer();pool.removeAllJobs(true,-1);setLookAndFeel(nullptr);}
void WaveMoverEditor::paint(juce::Graphics&g){g.fillAll(background);g.setColour(orange);g.fillRect(0,0,getWidth(),5);g.setFont(juce::Font(25.f,juce::Font::bold));g.drawText("INVERSO  WaveMover",18,14,500,35,juce::Justification::left);g.setColour(text.withAlpha(.55f));g.setFont(13.f);g.drawText("CREATIVE SAMPLE EDITOR   /   0.1.0",getWidth()-360,18,340,30,juce::Justification::right);}
void WaveMoverEditor::resized(){auto r=getLocalBounds().reduced(15);r.removeFromTop(44);row(r.removeFromTop(38),{&open,&capture,&play,&stop,&loop,&original});information.setBounds(r.removeFromTop(28));auto grade=r.removeFromTop(32);labelBpm.setBounds(grade.removeFromLeft(105));bpm.setBounds(grade.removeFromLeft(260));gridDivision.setBounds(grade.removeFromLeft(155));fit.setBounds(grade.removeFromRight(130).reduced(3));row(r.removeFromTop(37),{&all,&split,&grid,&attacks,&clear,&undo,&redo});auto bottom=r.removeFromBottom(255);wave.setBounds(r.reduced(3));details.setBounds(bottom.removeFromTop(25));row(bottom.removeFromTop(37),{&cut,&copy,&paste,&duplicate,&trim,&crossfade,&restore});auto fx=bottom.removeFromTop(38);effects.setBounds(fx.removeFromLeft(fx.getWidth()/2).reduced(3));seed.setBounds(fx.removeFromRight(110).reduced(4));apply.setBounds(fx.reduced(3));auto p1=bottom.removeFromTop(35);labelA.setBounds(p1.removeFromLeft(240));a.setBounds(p1);auto p2=bottom.removeFromTop(35);labelB.setBounds(p2.removeFromLeft(240));b.setBounds(p2);row(bottom.removeFromTop(38),{&exportSelection,&save,&drag});status.setBounds(bottom.reduced(3));}
void WaveMoverEditor::timerCallback(){if(processor.captureReady())capture.onClick();auto s=processor.snapshot();if(s.revision!=seenRevision){seenRevision=s.revision;drag.readyFile={};drag.setButtonText("Preparar arraste");wave.viewStart=std::clamp(wave.viewStart,0.,1.-wave.viewSize);wave.cursor=s.audio?std::min(wave.cursor,s.audio->frames()):0;wave.refresh();}else wave.repaint();updateControls();}
void WaveMoverEditor::updateControls(){auto s=processor.snapshot();const bool audio=s.audio&&s.audio->frames(),captureActive=processor.recording()||processor.captureReady();const bool enabled=!busy&&!captureActive;for(auto*c:std::vector<juce::Component*>{&open,&all,&split,&grid,&attacks,&clear,&cut,&copy,&paste,&duplicate,&trim,&crossfade,&restore,&effects,&a,&b,&apply,&save,&drag,&original,&play,&exportSelection})c->setEnabled(enabled&&(c==&open||audio));paste.setEnabled(enabled&&s.audio!=nullptr&&clipboard!=nullptr);restore.setEnabled(enabled&&s.original!=nullptr);original.setEnabled(enabled&&s.original!=nullptr);undo.setEnabled(enabled&&processor.canUndo());redo.setEnabled(enabled&&processor.canRedo());capture.setEnabled(!busy);capture.setButtonText(captureActive?"Finalizar captura":"Capturar pista");wave.editable=enabled;
    if(audio){const auto r=bounded(s.selection,s.audio->frames());information.setText(s.name+"   |   "+juce::String(s.audio->rate,0)+" Hz   |   "+juce::String(s.audio->channels())+" canal(is)   |   "+juce::String(static_cast<double>(s.audio->frames())/s.audio->rate,3)+" s   |   Selecao: "+juce::String(static_cast<double>(r.end-r.begin)/s.audio->rate,3)+" s   |   "+juce::String(static_cast<int>(s.markers.size()+1))+" fatias",juce::dontSendNotification);}else information.setText("WAV / AIFF / FLAC / MP3 / OGG   |   Mono ou estereo   |   Original preservado",juce::dontSendNotification);
    if(processor.recording())status.setText("CAPTURANDO  "+juce::String(processor.capturedSeconds(),1)+" s / ate 120 s. Clique Finalizar captura.",juce::dontSendNotification);
}
void WaveMoverEditor::configureEffect(){const auto op=operations[static_cast<std::size_t>(effects.getSelectedId()-1)];juce::String la="A (sem parametro)",lb="B (sem parametro)";double amin=0,amax=1,av=0,bmin=0,bmax=1,bv=0,astep=.01,bstep=.01;
    switch(op){case Op::FadeIn:case Op::FadeOut:case Op::FadeBoth:la="Duracao do fade (ms)";amin=0;amax=10000;av=50;lb="Curva (1 = linear)";bmin=.1;bmax=5;bv=1;break;case Op::Stretch:la="Duracao resultante (%)";amin=25;amax=400;av=100;break;case Op::Pitch:la="Afinacao (semitons)";amin=-24;amax=24;av=0;astep=.01;break;case Op::Tempo:case Op::TempoRamp:la="BPM de origem / inicio";amin=20;amax=400;av=bpm.getValue();lb=op==Op::Tempo?"BPM de destino":"BPM no final da rampa";bmin=20;bmax=400;bv=90;break;case Op::Speed:la="Velocidade (x)";amin=.25;amax=4;av=1;break;case Op::Reverb:case Op::Tail:case Op::ReverseTail:la="Decaimento / cauda (s)";amin=.1;amax=15;av=2;lb="Nivel de reverb (%)";bmin=0;bmax=100;bv=op==Op::Reverb?35:100;break;case Op::Delay:la="Intervalo (ms)";amin=1;amax=4000;av=250;lb="Feedback (%)";bmin=0;bmax=90;bv=45;break;case Op::Lowpass:case Op::Highpass:la="Frequencia de corte (Hz)";amin=20;amax=20000;av=op==Op::Lowpass?3000:300;break;case Op::Saturate:la="Drive (dB)";amin=0;amax=36;av=6;break;case Op::Gain:la="Ganho (dB)";amin=-60;amax=24;av=0;break;case Op::Repeat:case Op::Ratchet:case Op::PingPong:la="Numero de repeticoes";amin=2;amax=32;av=4;astep=1;break;case Op::Freeze:la="Duracao da textura (s)";amin=.05;amax=30;av=3;lb="Tamanho dos graos (ms)";bmin=10;bmax=500;bv=80;break;default:break;}
    labelA.setText(la,juce::dontSendNotification);labelB.setText(lb,juce::dontSendNotification);a.setRange(amin,amax,astep);a.setValue(av);b.setRange(bmin,bmax,bstep);b.setValue(bv);
}
void WaveMoverEditor::work(juce::String label,std::function<std::function<void()>()>task){if(busy)return;busy=true;status.setText(label,juce::dontSendNotification);updateControls();auto safe=juce::Component::SafePointer<WaveMoverEditor>(this);pool.addJob([safe,task=std::move(task)]()mutable{std::function<void()>done;juce::String error;try{done=task();}catch(const std::exception&e){error=e.what();}catch(...){error="Falha inesperada; a versao anterior foi preservada.";}juce::MessageManager::callAsync([safe,done=std::move(done),error]()mutable{if(!safe)return;try{if(done)done();safe->status.setText(error.isEmpty()?"Pronto. Ouvir, desfazer ou exportar.":error,juce::dontSendNotification);}catch(const std::exception&e){safe->status.setText(e.what(),juce::dontSendNotification);}safe->busy=false;safe->timerCallback();});});}
void WaveMoverEditor::openFile(const juce::File&file){if(busy||processor.recording())return;auto*p=&processor;work("Carregando "+file.getFileName()+"...",[p,file]{auto audio=std::make_shared<Clip>(WaveMoverProcessor::readAudio(file));return[p,audio,file]()mutable{p->load(std::move(*audio),file.getFileName());};});}
void WaveMoverEditor::applyOperation(Op op,Parameters params,juce::String label){auto s=processor.snapshot();if(!s.audio||busy||processor.recording())return;Range r=bounded(s.selection,s.audio->frames());if(r.end==r.begin){status.setText("Selecione um trecho ou clique Selecionar tudo.",juce::dontSendNotification);return;}auto*p=&processor;work(label+"...",[s,r,op,params,p,label]{std::vector<std::size_t>local;for(auto m:s.markers)if(m>r.begin&&m<r.end)local.push_back(m-r.begin);auto transformed=render(section(*s.audio,r),op,params,local);const auto len=transformed.audio.frames();std::vector<std::size_t>markers;Clip out;
        if(op==Op::Trim){out=std::move(transformed.audio);markers=std::move(local);}else{out=splice(*s.audio,r,transformed.audio);const auto delta=static_cast<std::int64_t>(len)-static_cast<std::int64_t>(r.end-r.begin);for(auto m:s.markers){if(m<=r.begin)markers.push_back(m);else if(m>=r.end)markers.push_back(static_cast<std::size_t>(static_cast<std::int64_t>(m)+delta));else if(op!=Op::Shuffle&&op!=Op::Ratchet&&op!=Op::Repeat&&op!=Op::PingPong&&op!=Op::Duplicate&&len)markers.push_back(r.begin+static_cast<std::size_t>(static_cast<double>(m-r.begin)*static_cast<double>(len)/static_cast<double>(r.end-r.begin)));}for(auto m:transformed.markers)markers.push_back(r.begin+m);}
        auto audio=std::make_shared<Clip>(std::move(out));const Range selected=op==Op::Trim?Range{0,len}:Range{r.begin,r.begin+len};return[p,audio,markers=std::move(markers),selected,label]()mutable{p->commit(std::move(*audio),std::move(markers),selected,label);};});}
void WaveMoverEditor::copyAudio(){auto s=processor.snapshot();if(s.audio&&s.selection.end>s.selection.begin){clipboard=std::make_shared<Clip>(section(*s.audio,s.selection));status.setText("Selecao copiada.",juce::dontSendNotification);}}
void WaveMoverEditor::pasteAudio(){auto s=processor.snapshot();auto clip=clipboard;if(!clip||!s.audio)return;auto*p=&processor;work("Colando...",[p,s,clip]{Clip converted=*clip;if(converted.rate!=s.audio->rate){converted=varispeed(converted,converted.rate/s.audio->rate,converted.rate/s.audio->rate);converted.rate=s.audio->rate;}if(converted.channels()!=s.audio->channels()){Clip mapped(s.audio->channels(),converted.frames(),converted.rate);for(int c=0;c<mapped.channels();++c)for(std::size_t j=0;j<mapped.frames();++j)mapped.data[c][j]=mapped.channels()==1?.5f*(converted.data[0][j]+converted.data[1][j]):converted.data[0][j];converted=std::move(mapped);}const auto r=s.selection;const auto n=converted.frames();auto audio=std::make_shared<Clip>(splice(*s.audio,r,converted));std::vector<std::size_t>markers;const auto delta=static_cast<std::int64_t>(n)-static_cast<std::int64_t>(r.end-r.begin);for(auto m:s.markers){if(m<=r.begin)markers.push_back(m);else if(m>=r.end)markers.push_back(static_cast<std::size_t>(static_cast<std::int64_t>(m)+delta));}return[p,audio,markers=std::move(markers),r,n]()mutable{p->commit(std::move(*audio),std::move(markers),{r.begin,r.begin+n},"Colar");};});}
void WaveMoverEditor::contextMenu(){juce::PopupMenu menu;menu.addItem(1,"Split no cursor");menu.addItem(2,"Selecionar tudo");menu.addItem(3,"Reverse da selecao");menu.addItem(4,"Apagar selecao");menu.addSeparator();menu.addItem(5,"Desfazer",processor.canUndo());menu.addItem(6,"Refazer",processor.canRedo());menu.showMenuAsync(juce::PopupMenu::Options().withTargetComponent(&wave),[safe=juce::Component::SafePointer<WaveMoverEditor>(this)](int id){if(!safe)return;switch(id){case 1:safe->split.onClick();break;case 2:safe->all.onClick();break;case 3:safe->applyOperation(Op::Reverse,{},"Reverse");break;case 4:safe->cut.onClick();break;case 5:safe->processor.undo();break;case 6:safe->processor.redo();break;default:break;}});}
void WaveMoverEditor::exportAudio(bool forDrag){auto s=processor.snapshot();if(!s.audio||busy)return;const bool selected=exportSelection.getToggleState();auto perform=[safe=juce::Component::SafePointer<WaveMoverEditor>(this),s,selected,forDrag](juce::File file){if(!safe)return;safe->work("Exportando WAV 32-bit float...",[safe,s,selected,forDrag,file]{auto audio=selected?section(*s.audio,s.selection):*s.audio;WaveMoverProcessor::writeAudio(file,audio);return[safe,file,forDrag]{if(safe&&forDrag){safe->drag.readyFile=file;safe->drag.setButtonText("ARRASTE para a DAW");}};});};
    if(forDrag){auto directory=juce::File::getSpecialLocation(juce::File::userApplicationDataDirectory).getChildFile("INVERSO/WaveMover/Exports");perform(directory.getChildFile("WaveMover_"+juce::Uuid().toString()+".wav"));}
    else{chooser=std::make_unique<juce::FileChooser>("Exportar WAV 32-bit float",juce::File::getSpecialLocation(juce::File::userDocumentsDirectory).getChildFile("WaveMover.wav"),"*.wav");chooser->launchAsync(juce::FileBrowserComponent::saveMode|juce::FileBrowserComponent::canSelectFiles|juce::FileBrowserComponent::warnAboutOverwriting,[perform](const juce::FileChooser&f){if(f.getResult()!=juce::File{})perform(f.getResult().withFileExtension("wav"));});}}
bool WaveMoverEditor::isInterestedInFileDrag(const juce::StringArray&files){return !busy&&!processor.recording()&&files.size()==1;}
void WaveMoverEditor::filesDropped(const juce::StringArray&files,int,int){if(files.size()==1)openFile(juce::File(files[0]));else status.setText("Solte um arquivo por vez.",juce::dontSendNotification);}
bool WaveMoverEditor::keyPressed(const juce::KeyPress&key){if(busy||processor.recording())return false;if(key==juce::KeyPress::spaceKey){if(processor.playing())processor.stop();else processor.play(false,loop.getToggleState());return true;}if(key==juce::KeyPress::deleteKey||key==juce::KeyPress::backspaceKey){cut.onClick();return true;}if(key.getModifiers().isCommandDown()){const auto c=juce::CharacterFunctions::toLowerCase(key.getTextCharacter());if(c=='a'){all.onClick();return true;}if(c=='c'){copyAudio();return true;}if(c=='v'){pasteAudio();return true;}if(c=='z'){if(key.getModifiers().isShiftDown())processor.redo();else processor.undo();return true;}}return false;}
